"use client";
import Link from "next/link";

export default function Projects() {
  const projects = [
    {
      title: "Job Portal System",
      desc: "A web app where users can apply for jobs and employers can post jobs.",
      tech: "HTML, CSS, JS, PHP, MySQL",
      github: "#",
      live: "#",
    },
    {
      title: "MRI Detection App",
      desc: "AI-based system to detect diseases from MRI images.",
      tech: "Python, Flask",
      github: "#",
      live: "#",
    },
    {
      title: "Portfolio Website",
      desc: "Personal portfolio built with Next.js and Tailwind CSS.",
      tech: "Next.js, Tailwind",
      github: "#",
      live: "#",
    },
  ];

  return (
    <section
      id="projects"
      className="py-24 bg-gray-950 text-white px-6 md:px-20"
    >
      <h2 className="text-4xl md:text-5xl font-bold text-center mb-16">
        My <span className="text-cyan-400">Projects</span>
      </h2>

      <div className="grid md:grid-cols-3 gap-10 max-w-7xl mx-auto">
        {projects.map((project) => (
          <div
            key={project.title}
           className="glass rounded-2xl overflow-hidden hover:scale-105 hover:shadow-cyan-500/30 transition"
          >
            <h3 className="text-2xl font-semibold mb-3 text-cyan-400">
              {project.title}
            </h3>

            <p className="text-gray-300 mb-4">{project.desc}</p>

            <p className="text-sm text-gray-400 mb-4">
              Tech: {project.tech}
            </p>

            <div className="flex gap-4">
              <Link
                href={project.github}
                className="bg-gray-700 px-4 py-2 rounded-lg hover:bg-gray-600"
              >
                GitHub
              </Link>

              <Link
                href={project.live}
                className="bg-cyan-600 px-4 py-2 rounded-lg hover:bg-cyan-500"
              >
                Live Demo
              </Link>
            </div>
          </div>
        ))}
      </div>
    </section>
  );
}